ga0g(){return"\uc785\ud78c \ud53c\ud574\uc758 \uc77c\ubd80\ub9cc\ud07c \ud68c\ubcf5\ud574\uc694."},
ga0h(){return"\uacf5\uaca9\uc790\uac00 \uc785\ud78c \ud53c\ud574\uc758 \uc77c\ubd80\uac00 \ud0c0\uaca9\ub9c8\ub2e4 <hp>\uccb4\ub825</hp>\uc73c\ub85c \ub3cc\uc544\uc640\uc694."},
ga0i(){return"\ud134 \uac8c\uc774\uc9c0 \uc77c\ubd80\ub97c \ube44\uc6cc\uc694."},
ga0j(){return"\ud134 \uac8c\uc774\uc9c0 \uac10\uc18c\ub294 \ub300\uc0c1\uc758 \ud134 \uac8c\uc774\uc9c0\ub97c \uc77c\uc815 \ube44\uc728 \uae4e\uc544 \ub2e4\uc74c \ud134\uc774 \ub2a6\uac8c \uc640\uc694."},
ga0k(){return"\ud134 \uac8c\uc774\uc9c0 \uc77c\ubd80\ub97c \ucc44\uc6cc\uc694."},
