ga0v(){return"\ubd80\ud65c\uc740 \uc4f0\ub7ec\uc9c4 Ovaling\uc744 <hp>\uccb4\ub825</hp> \uc77c\ubd80\uc640 \ud568\uaed8 \uc804\ud22c\ub85c \ub418\ub3cc\ub824\uc694. \uac01 Ovaling\uc740 \uc804\ud22c\ub9c8\ub2e4 \ud55c \ubc88\ub9cc \ubd80\ud65c\ud560 \uc218 \uc788\uc5b4\uc694."},
gZa(){return"<fx:poison>\ub3c5</fx>\uc5d0 \uba74\uc5ed."},
gZb(){return"\uc5ec\uc655\uc758 <fx:poison>\ub3c5</fx>\uc740 \ucd5c\ub300 3\ubc88 \uc911\ucca9\ub3fc\uc694."},
